  // Only a viewer becoming billable takes a new seat; an active member's seat
  // is what the counter tracks, so a non-active member takes none.
  const takesSeat =
    member.status === "active" &&
    !isBillableRole(member.role) &&
    isBillableRole(input.role);
  await assertSeatsAvailable(input.orgId, takesSeat ? 1 : 0);

