describe("seats on role change", () => {
  // A viewer becoming billable needs a seat; the free plan has none left.
  it("refuses a viewer becoming billable when the plan's seats are taken", async () => {
    const tenant = await createTenant("role-seat-full", "free");
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture viewer missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    const unchanged = await memberRepo.findMemberById(tenant.org.id, viewer.id);
    expect(unchanged?.role).toBe("viewer");
  });

  // Changes between billable roles, and demotions to viewer, never take a seat.
  it("allows billable-to-billable and demotion-to-viewer changes on a full plan", async () => {
    const tenant = await createTenant("role-seat-free-moves", "free");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!admin || !member) throw new Error("fixture member missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
        role: "member",
      }),
    ).resolves.toMatchObject({ role: "member" });

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
        role: "viewer",
      }),
    ).resolves.toMatchObject({ role: "viewer" });
  });

  // The incremental counter must land on the same figure a full recount gives.
  it("keeps the seat counter equal to a full recount across role changes", async () => {
    const tenant = await createTenant("role-seat-counter", "growth");
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture viewer missing");

    const detach = [usageService.registerUsageListeners()];
    try {
      await usageService.recomputeUsage(tenant.org.id);
      const baseline = (await usageRepo.getUsage(tenant.org.id)).seatsUsed;
      expect(baseline).toBe(3);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "admin",
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "viewer",
      });
      const incremental = (await usageRepo.getUsage(tenant.org.id)).seatsUsed;

      const recounted = await usageRepo.recomputeUsage(tenant.org.id);
      expect(incremental).toBe(3);
      expect(recounted.seatsUsed).toBe(incremental);
    } finally {
      for (const off of detach) off();
    }
  });
});
'''
p.write_text(s)
EOF
